// src/app/classes/auth.guard.ts
var authGuard = () => {
  const router = inject(Router);
  const isLoggedIn = localStorage.getItem("isLoggedIn") === "true";
  return isLoggedIn ? true : router.parseUrl("/login");
};

// src/app/classes/CourseRegistration.ts
var CourseRegistration = class {
  constructor(fullName = "", email = "", phone = "", course = "", shift = "sang", agree = true) {
    this.fullName = fullName;
    this.email = email;
    this.phone = phone;
    this.course = course;
    this.shift = shift;
    this.agree = agree;
  }
  fullName;
  email;
  phone;
  course;
  shift;
  agree;
  getInfor() {
    let infor = "Full Name = " + this.fullName + "\nEmail=" + this.email + "\nPhone=" + this.phone + "\nCourse=" + this.course + "\nShift=" + this.shift + "\nAgree=" + this.agree;
    return infor;
  }
};

